<script setup lang="ts">
import { computed, defineAsyncComponent } from "vue";
import type { CommandAuthority, CommandPort } from "../operations/command-port";
import type { MetricSeriesView, OperationsSnapshot, PositionView } from "../operations/operations-port";

type OperationsPane = "overview" | "positions" | "orders" | "signals" | "activity" | "sources";
const props = defineProps<{
  snapshot: OperationsSnapshot;
  activePane: OperationsPane;
  connectionLabel: string;
  stale: boolean;
  authority: CommandAuthority;
  port: CommandPort;
  selectedSignalId: string;
  selectedOrderId: string;
  selectedMetricId: string;
}>();
const emit = defineEmits<{
  authority: [authority: CommandAuthority];
  explore: [];
  selectSignal: [id: string];
  selectOrder: [id: string];
  selectMetric: [id: string];
}>();
const TimeSeriesChart = defineAsyncComponent(() => import("./TimeSeriesChart.vue"));
const NewOrderTicket = defineAsyncComponent(() => import("./NewOrderTicket.vue"));

const selectedSignal = computed(() => props.snapshot.signals.find((item) => item.id === props.selectedSignalId) ?? props.snapshot.signals[0]);
const selectedOrder = computed(() => props.snapshot.orders.find((item) => item.clientOrderId === props.selectedOrderId) ?? props.snapshot.orders[0]);
const selectedMetric = computed(() => props.snapshot.metrics.find((item) => item.id === props.selectedMetricId) ?? props.snapshot.metrics[0]);
const selectedSignalSeries = computed<MetricSeriesView | undefined>(() => {
  const signal = selectedSignal.value;
  if (!signal) return undefined;
  const observedAt = new Date(props.snapshot.observedAt).getTime();
  return {
    id: `signal-${signal.id}`,
    label: signal.hypothesis,
    unit: "%",
    tone: signal.state === "blocked" ? "coral" : signal.state === "eligible" ? "green" : "cyan",
    points: signal.trace.map((point) => ({ timestamp: new Date(observedAt + point.offsetSeconds * 1_000).toISOString(), value: point.valueBps / 100 })),
    referenceLines: [{ label: "50%", value: 50, tone: "neutral" }],
  };
});
const grossUtilization = computed(() => {
  const gross = BigInt(props.snapshot.risk.grossExposureMicros);
  const limit = BigInt(props.snapshot.risk.grossLimitMicros);
  return limit === 0n ? 0 : Number((gross * 1_000_000n) / limit) / 1_000_000;
});
const unrealizedTotal = computed(() => props.snapshot.positions.reduce((total, position) => total + BigInt(position.unrealizedPnlMicros), 0n));
const marketValueTotal = computed(() => props.snapshot.positions.reduce((total, position) => total + absolute(BigInt(position.marketValueMicros)), 0n));
const dayPnlTotal = computed(() => props.snapshot.positions.reduce((total, position) => total + BigInt(position.dayPnlMicros ?? "0"), 0n));

function strategyName(id: string): string { return props.snapshot.strategies.find((item) => item.id === id)?.name ?? id; }
function absolute(value: bigint): bigint { return value < 0n ? -value : value; }
function money(micros: string | bigint, signed = false): string {
  const value = BigInt(micros);
  const negative = value < 0n;
  const absoluteValue = negative ? -value : value;
  const roundedCents = (absoluteValue + 5_000n) / 10_000n;
  const dollars = roundedCents / 100n;
  const cents = roundedCents % 100n;
  const prefix = negative ? "-" : signed ? "+" : "";
  const whole = new Intl.NumberFormat("en-US", { maximumFractionDigits: 0 }).format(dollars);
  return `${prefix}$${whole}${dollars < 100n || cents !== 0n ? `.${cents.toString().padStart(2, "0")}` : ""}`;
}
function quantity(micros: string): string {
  const value = BigInt(micros);
  const negative = value < 0n;
  const absoluteValue = negative ? -value : value;
  const whole = new Intl.NumberFormat("en-US", { maximumFractionDigits: 0 }).format(absoluteValue / 1_000_000n);
  const fraction = (absoluteValue % 1_000_000n).toString().padStart(6, "0").replace(/0+$/, "");
  return `${negative ? "-" : ""}${whole}${fraction ? `.${fraction}` : ""}`;
}
function percent(bps: number): string { return `${(bps / 100).toFixed(1)}%`; }
function ratioBps(numerator: string, denominator: bigint): number {
  if (denominator === 0n) return 0;
  return Number((BigInt(numerator) * 1_000_000n) / denominator) / 100;
}
function positionCostMicros(position: PositionView): bigint { return (absolute(BigInt(position.quantityMicros)) * BigInt(position.averagePriceMicros)) / 1_000_000n; }
function positionOpenBps(position: PositionView): number { return ratioBps(position.unrealizedPnlMicros, positionCostMicros(position)); }
function shortId(id: string): string { return id.length <= 14 ? id : `${id.slice(0, 6)}…${id.slice(-4)}`; }
</script>

<template>
  <div class="operations-pane">
    <template v-if="activePane === 'overview'">
      <section class="metric-strip" aria-label="Account summary"><dl>
        <div><dt>Gross exposure</dt><dd>{{ money(snapshot.risk.grossExposureMicros) }}</dd><small>{{ (grossUtilization * 100).toFixed(1) }}% of limit</small></div>
        <div><dt>Unrealized P&amp;L</dt><dd :class="{ negative: unrealizedTotal < 0n }">{{ money(unrealizedTotal, true) }}</dd><small>{{ snapshot.positions.length }} positions</small></div>
        <div><dt>Active orders</dt><dd>{{ snapshot.orders.length }}</dd><small>{{ snapshot.risk.pendingReconciliations }} unreconciled</small></div>
        <div><dt>Orders today</dt><dd>{{ snapshot.risk.dailyOrderCount }} / {{ snapshot.risk.dailyOrderLimit }}</dd><small>Account limit</small></div>
        <div><dt>Source lag</dt><dd :class="{ caution: snapshot.risk.sourceLagMs > 2_000 }">{{ snapshot.risk.sourceLagMs.toLocaleString() }}ms</dd><small>Worst source</small></div>
      </dl></section>
      <section class="telemetry-section"><header class="section-header"><h1>Portfolio telemetry</h1><div class="metric-tabs" role="tablist" aria-label="Portfolio metric"><button v-for="metric in snapshot.metrics" :key="metric.id" role="tab" :aria-selected="selectedMetric?.id === metric.id" @click="emit('selectMetric', metric.id)">{{ metric.label }}</button></div></header><TimeSeriesChart v-if="selectedMetric" :series="selectedMetric" /><p v-else class="empty-state">No telemetry series</p></section>
      <section class="account-register" aria-label="Account runtime"><dl><div><dt>Capital gate</dt><dd :class="snapshot.risk.capitalGate === 'authorized' ? 'positive' : 'caution'">{{ snapshot.risk.capitalGate }}</dd></div><div><dt>Reserved gross</dt><dd>{{ money(snapshot.risk.reservedGrossMicros) }}</dd></div><div><dt>Open incidents</dt><dd>{{ snapshot.risk.openIncidents }}</dd></div><div><dt>Sequence</dt><dd>{{ snapshot.sequence.toLocaleString() }}</dd></div><div><dt>Checkpoint</dt><dd>{{ snapshot.risk.checkpointAgeMs }}ms</dd></div></dl></section>
    </template>

    <section v-else-if="activePane === 'positions'" class="pane-section" aria-labelledby="positions-heading"><header class="pane-heading"><div><h1 id="positions-heading">Positions</h1><span>{{ snapshot.positions.length }} open</span></div><time :datetime="snapshot.observedAt">Marks {{ connectionLabel.toLowerCase() }}</time></header><div class="position-summary"><dl><div><dt>Market value</dt><dd>{{ money(marketValueTotal) }}</dd></div><div><dt>Open P&amp;L</dt><dd :class="unrealizedTotal >= 0n ? 'positive' : 'negative'">{{ money(unrealizedTotal, true) }}</dd></div><div><dt>Day P&amp;L</dt><dd :class="dayPnlTotal >= 0n ? 'positive' : 'negative'">{{ money(dayPnlTotal, true) }}</dd></div><div><dt>Gross limit</dt><dd>{{ money(snapshot.risk.grossLimitMicros) }}</dd></div></dl></div><div class="table-scroll" tabindex="0" aria-label="Positions. Scroll horizontally for value and change columns."><table class="positions-table"><thead><tr><th>Instrument</th><th>Strategy</th><th class="number">Quantity</th><th class="number">Average</th><th class="number">Mark</th><th class="number">Market value</th><th class="number">Open P&amp;L</th><th class="number">Open %</th><th class="number">Day P&amp;L</th><th class="number">Day %</th><th class="number">Mark age</th></tr></thead><tbody><tr v-for="position in snapshot.positions" :key="`${position.instrument}:${position.strategy}`"><th>{{ position.instrument }}</th><td>{{ strategyName(position.strategy) }}</td><td class="number">{{ quantity(position.quantityMicros) }}</td><td class="number">{{ money(position.averagePriceMicros) }}</td><td class="number">{{ money(position.markPriceMicros) }}</td><td class="number">{{ money(position.marketValueMicros) }}</td><td class="number" :class="BigInt(position.unrealizedPnlMicros) >= 0n ? 'positive' : 'negative'">{{ money(position.unrealizedPnlMicros, true) }}</td><td class="number" :class="positionOpenBps(position) >= 0 ? 'positive' : 'negative'">{{ percent(positionOpenBps(position)) }}</td><td class="number" :class="BigInt(position.dayPnlMicros ?? '0') >= 0n ? 'positive' : 'negative'">{{ money(position.dayPnlMicros ?? '0', true) }}</td><td class="number" :class="(position.dayChangeBps ?? 0) >= 0 ? 'positive' : 'negative'">{{ percent(position.dayChangeBps ?? 0) }}</td><td class="number">{{ position.freshnessMs }}ms</td></tr></tbody></table></div></section>

    <section v-else-if="activePane === 'orders'" class="pane-section" aria-labelledby="orders-heading"><header class="pane-heading"><div><h1 id="orders-heading">Orders</h1><span>{{ snapshot.orders.length }} active</span></div><time :datetime="snapshot.observedAt">OMS sequence {{ snapshot.sequence.toLocaleString() }}</time></header><div class="orders-grid"><Suspense><NewOrderTicket :authority="authority" :port="port" :snapshot="snapshot" :stale="stale" @authority="emit('authority', $event)"/><template #fallback><div class="ticket-loading">Loading order ticket</div></template></Suspense><section class="active-orders" aria-labelledby="active-orders-heading"><header class="section-header"><h2 id="active-orders-heading">Active orders</h2><span>{{ snapshot.orders.length }}</span></header><div class="order-register"><button v-for="order in snapshot.orders" :key="order.clientOrderId" :class="{ selected: selectedOrder?.clientOrderId === order.clientOrderId }" @click="emit('selectOrder', order.clientOrderId)"><span :data-side="order.side">{{ order.side }}</span><strong>{{ order.instrument }}</strong><b>{{ order.state.replaceAll('_', ' ') }}</b><small>{{ strategyName(order.strategy) }}</small><code>{{ shortId(order.clientOrderId) }}</code></button></div><dl v-if="selectedOrder" class="order-detail"><div><dt>Venue</dt><dd>{{ selectedOrder.venue }}</dd></div><div><dt>Quantity</dt><dd>{{ quantity(selectedOrder.quantityMicros) }}</dd></div><div><dt>Filled</dt><dd>{{ quantity(selectedOrder.filledQuantityMicros) }}</dd></div><div><dt>Limit</dt><dd>{{ money(selectedOrder.limitPriceMicros) }}</dd></div><div><dt>Reconciliation</dt><dd>{{ selectedOrder.reconciliation }}</dd></div><div><dt>OMS version</dt><dd>{{ selectedOrder.omsVersion ?? "n/a" }}</dd></div></dl><p v-else class="empty-state">No active orders</p></section></div><section class="fills-section" aria-labelledby="fills-heading"><header class="section-header"><h2 id="fills-heading">Executions</h2><span>{{ snapshot.fills.length }}</span></header><div class="table-scroll" tabindex="0" aria-label="Executions. Scroll horizontally for all columns."><table><thead><tr><th>Execution</th><th>Instrument</th><th>Side</th><th class="number">Quantity</th><th class="number">Price</th><th>Venue</th><th>Strategy</th><th>Liquidity</th><th>Time</th></tr></thead><tbody><tr v-for="fill in snapshot.fills" :key="fill.executionId"><th>{{ shortId(fill.executionId) }}</th><td>{{ fill.instrument }}</td><td :class="fill.side === 'buy' ? 'positive' : 'negative'">{{ fill.side }}</td><td class="number">{{ quantity(fill.quantityMicros) }}</td><td class="number">{{ money(fill.priceMicros) }}</td><td>{{ fill.venue }}</td><td>{{ strategyName(fill.strategy) }}</td><td>{{ fill.liquidity }}</td><td>{{ fill.executedAt }}</td></tr></tbody></table></div></section></section>

    <section v-else-if="activePane === 'signals'" class="pane-section" aria-labelledby="signals-heading"><header class="pane-heading"><div><h1 id="signals-heading">Signals</h1><span>{{ snapshot.signals.length }} candidates</span></div><time :datetime="snapshot.observedAt">Decision state</time></header><div class="signal-layout"><div class="signal-register" role="list"><button v-for="signal in snapshot.signals" :key="signal.id" :class="{ selected: selectedSignal?.id === signal.id }" @click="emit('selectSignal', signal.id)"><i :data-state="signal.state" aria-hidden="true"></i><span><strong>{{ signal.hypothesis }}</strong><small>{{ strategyName(signal.strategyId) }} · {{ signal.instrument }} · {{ signal.horizon }}</small></span><b>{{ percent(signal.posteriorBps) }}</b></button></div><article v-if="selectedSignal" class="signal-inspector"><header><div><h2>{{ selectedSignal.hypothesis }}</h2><span>{{ selectedSignal.instrument }} · {{ selectedSignal.state }}</span></div><strong>{{ percent(selectedSignal.posteriorBps) }}</strong></header><TimeSeriesChart v-if="selectedSignalSeries" :series="selectedSignalSeries" /><dl><div><dt>Trigger</dt><dd>{{ selectedSignal.trigger }}</dd></div><div><dt>Decision cut</dt><dd>{{ selectedSignal.decisionCut }}</dd></div><div><dt>Action</dt><dd>{{ selectedSignal.action }}</dd></div><div v-if="selectedSignal.blocker"><dt>Blocker</dt><dd class="negative">{{ selectedSignal.blocker }}</dd></div></dl><ol aria-label="Signal lineage"><li v-for="step in selectedSignal.lineage" :key="step">{{ step }}</li></ol></article><p v-else class="empty-state">No signal candidates</p></div></section>

    <section v-else-if="activePane === 'activity'" class="pane-section" aria-labelledby="activity-heading"><header class="pane-heading"><div><h1 id="activity-heading">Activity</h1><span>{{ snapshot.activity.length }} recent</span></div><time :datetime="snapshot.observedAt">Sequence {{ snapshot.sequence.toLocaleString() }}</time></header><div class="activity-table" role="table" aria-label="Recent OMS activity"><div class="activity-head" role="row"><span role="columnheader">Time</span><span role="columnheader">Category</span><span role="columnheader">Entity</span><span role="columnheader">Stage</span><span role="columnheader">Outcome</span></div><div v-for="item in snapshot.activity" :key="item.id" role="row" :data-severity="item.severity"><code role="cell">{{ item.occurredAt }}</code><strong role="cell">{{ item.category }}</strong><span role="cell">{{ item.entity }}</span><small role="cell">{{ item.stage }}</small><b role="cell">{{ item.outcome }}</b></div></div></section>

    <section v-else class="pane-section sources-section" aria-labelledby="sources-heading"><header class="pane-heading"><div><h1 id="sources-heading">Sources</h1><span>{{ snapshot.sources.length }} connected</span></div><button @click="emit('explore')">Open data explorer</button></header><ul><li v-for="source in snapshot.sources" :key="`${source.name}:${source.channel}`" :data-health="source.health"><i aria-hidden="true"></i><div><strong>{{ source.name }}</strong><span>{{ source.channel }}</span></div><dl><div><dt>Lag</dt><dd>{{ source.lagMs.toLocaleString() }}ms</dd></div><div><dt>Watermark</dt><dd>{{ source.watermark }}</dd></div></dl><small>{{ source.detail }}</small></li></ul></section>
  </div>
</template>

