.signal-layout{display:grid;grid-template-columns:minmax(280px,.62fr) minmax(0,1.38fr);min-height:calc(100vh - 136px);background:var(--operator-black)}.signal-register{border-right:1px solid var(--atlas-rule)}.signal-register button{display:grid;grid-template-columns:8px minmax(0,1fr) auto;gap:10px;align-items:start;width:100%;min-height:72px;padding:13px 14px;text-align:left;border:0;border-bottom:1px solid var(--atlas-rule-soft);background:transparent;cursor:pointer}.signal-register button:hover,.signal-register button.selected{background:var(--atlas-blue-soft)}.signal-register i{width:7px;height:7px;margin-top:3px;border-radius:50%;background:var(--atlas-blue)}.signal-register i[data-state=eligible]{background:var(--atlas-green)}.signal-register i[data-state=blocked]{background:var(--atlas-oxide)}.signal-register span{display:grid;gap:5px;min-width:0}.signal-register strong{overflow:hidden;color:var(--atlas-ink);font-size:11px;text-overflow:ellipsis;white-space:nowrap}.signal-register small{overflow:hidden;color:var(--atlas-axis);font:8px var(--vp-font-family-mono);text-overflow:ellipsis;white-space:nowrap}.signal-register b{color:var(--atlas-green-ink);font:11px var(--vp-font-family-mono)}.signal-inspector{min-width:0;padding:18px}.signal-inspector>header{display:flex;justify-content:space-between;align-items:flex-start;gap:20px}.signal-inspector h2{margin:0;font-size:16px}.signal-inspector header span{color:var(--atlas-muted);font:8px var(--vp-font-family-mono);text-transform:uppercase}.signal-inspector header>strong{color:var(--atlas-green-ink);font:24px var(--vp-font-family-mono)}.signal-inspector dl{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));margin:4px 0 0;border:1px solid var(--atlas-rule)}.signal-inspector dl>div{min-width:0;padding:9px;border-right:1px solid var(--atlas-rule-soft)}.signal-inspector dt{color:var(--atlas-axis);font:8px var(--vp-font-family-mono);text-transform:uppercase}.signal-inspector dd{overflow:hidden;margin:5px 0 0;color:var(--atlas-muted);font-size:9px;text-overflow:ellipsis;white-space:nowrap}.signal-inspector ol{display:flex;flex-wrap:wrap;margin:12px 0 0;padding:0;list-style:none}.signal-inspector li{color:var(--atlas-blue);font:8px var(--vp-font-family-mono)}.signal-inspector li:not(:last-child)::after{margin:0 7px;color:var(--atlas-axis);content:"→"}
.sources-section ul{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));margin:0;padding:0;list-style:none}.sources-section li{display:grid;grid-template-columns:8px minmax(0,1fr) auto;gap:8px 10px;align-items:center;min-height:96px;padding:14px 16px;border-right:1px solid var(--atlas-rule-soft);border-bottom:1px solid var(--atlas-rule-soft)}.sources-section li>i{width:7px;height:7px;border-radius:50%;background:var(--atlas-green)}.sources-section li[data-health=degraded]>i,.sources-section li[data-health=stale]>i{background:var(--atlas-oxide)}.sources-section li>div{display:grid;gap:3px}.sources-section strong{font-size:11px}.sources-section span,.sources-section small{color:var(--atlas-muted);font:8px var(--vp-font-family-mono)}.sources-section li>dl{display:grid;gap:4px;margin:0}.sources-section li>dl div{display:flex;justify-content:space-between;gap:8px}.sources-section dt,.sources-section dd{margin:0;color:var(--atlas-axis);font:7px var(--vp-font-family-mono);text-transform:uppercase}.sources-section dd{color:var(--atlas-muted)}.sources-section li>small{grid-column:2/-1}.empty-state{display:grid;min-height:80px;place-items:center;margin:0;color:var(--atlas-axis);font:9px var(--vp-font-family-mono);text-transform:uppercase}
